"""
Recipe Scaler and Shopping-List Generator

See README.md for usage instructions.
"""

import json
import copy
from collections import defaultdict

class UnitConverter:
    """Handles conversion between measurement units (volume, mass, count, etc)."""
    def __init__(self, unit_table):
        self.unit_table = unit_table

    def to_base(self, quantity, unit):
        """Converts a quantity to its base unit (e.g., cups to ml)."""
        # placeholder
        return quantity, unit

    def from_base(self, quantity, unit, target_unit):
        """Converts a base unit to a target unit."""
        # placeholder
        return quantity, target_unit

    def can_convert(self, from_unit, to_unit):
        return from_unit == to_unit  # placeholder

class Ingredient:
    """Represents an ingredient and performs scaling and merging."""
    def __init__(self, name, quantity, unit):
        self.name = name.lower()
        self.quantity = float(quantity)
        self.unit = unit.lower()

    def __repr__(self):
        return f"{self.quantity} {self.unit} {self.name}"

class Recipe:
    """Represents a full recipe."""
    def __init__(self, ingredients, servings):
        self.ingredients = ingredients  # list of Ingredient
        self.servings = servings

    def scale(self, new_servings):
        factor = float(new_servings) / self.servings
        scaled = [Ingredient(ing.name, ing.quantity * factor, ing.unit) for ing in self.ingredients]
        return Recipe(scaled, new_servings)

class ShoppingList:
    """Handles ingredient merging and pantry subtraction."""
    def __init__(self):
        self.items = defaultdict(list)  # name -> list of (quantity, unit)

    def add_ingredient(self, ingredient):
        self.items[ingredient.name].append((ingredient.quantity, ingredient.unit))

    def merge(self, unit_converter):
        # placeholder: just sum if same unit
        merged = {}
        for name, qlist in self.items.items():
            total = defaultdict(float)
            for qty, unit in qlist:
                total[unit] += qty
            merged[name] = dict(total)
        return merged

    def subtract_pantry(self, pantry):
        # pantry: dict name->(qty,unit)
        after = {}
        for name, units in self.items.items():
            if name in pantry:
                pantry_qty, pantry_unit = pantry[name]
                # Placeholder: only works if units match
                after_qty = sum(q for q, u in units if u == pantry_unit) - pantry_qty
                if after_qty > 0:
                    after[name] = {pantry_unit: after_qty}
            else:
                after[name] = {u: q for q, u in units}
        return after
