class IngredientNormalizer:
    """
    Utility class for normalizing and synonym-mapping of ingredient names, units, and inference from config.
    """
    def __init__(self, config):
        self.synonyms = config.get('ingredient_synonyms', {})
        self.unit_synonyms = config['unit_table'].get('unit_synonyms', {})

    def normalize_name(self, name):
        base = name.strip().lower()
        if base in self.synonyms:
            return self.synonyms[base]
        return base

    def normalize_unit(self, unit):
        base = unit.strip().lower()
        if base in self.unit_synonyms:
            return self.unit_synonyms[base]
        return base

class UnitConverter:
    """
    Enhanced unit converter managing conversions within volume, mass, and count categories.
    """
    def __init__(self, unit_table):
        self.unit_table = unit_table
        self.synonyms = unit_table.get('unit_synonyms', {})
        # build unit→category map for reverse lookup
        self.unit_to_category = {}
        for cat, udict in unit_table.items():
            if isinstance(udict, dict):
                for u in udict.keys():
                    self.unit_to_category[u] = cat

    def resolve_unit(self, unit):
        unit = unit.lower() 
        return self.synonyms.get(unit, unit)

    def category(self, unit):
        unit = self.resolve_unit(unit)
        return self.unit_to_category.get(unit)

    def to_base(self, quantity, unit):
        """
        Converts a quantity in a unit to canonical base unit (ml, g, each).
        """
        u = self.resolve_unit(unit)
        cat = self.category(u)
        if not cat or cat == 'unit_synonyms' or u not in self.unit_table[cat]:
            raise ValueError(f"Unknown or incompatible unit {unit}")
        factor = self.unit_table[cat][u]
        base_qty = float(quantity) * factor
        # Return as (quantity_in_base, base_unit), e.g. (250, 'ml')
        if cat == 'volume':
            return (base_qty, 'ml')
        if cat == 'mass':
            return (base_qty, 'g')
        if cat == 'count':
            # For count, 'each' is canonical
            return (base_qty, 'each')
        raise ValueError(f"Unhandled unit category: {cat}")

    def from_base(self, base_quantity, base_unit, target_unit):
        """
        Convert from canonical base (ml/g/each) to any unit in its category.
        """
        target = self.resolve_unit(target_unit)
        cat = self.category(target)
        if not cat or cat == 'unit_synonyms' or target not in self.unit_table[cat]:
            raise ValueError(f"Unknown or incompatible target unit {target_unit}")
        base = {'volume':'ml', 'mass':'g', 'count':'each'}[cat]
        if base != base_unit:
            raise ValueError(f"Base unit {base_unit} does not match category {cat}")
        factor = self.unit_table[cat][target]
        return base_quantity / factor, target

    def can_convert(self, from_unit, to_unit):
        """
        Returns True if from_unit and to_unit are in same category and convertible.
        """
        u1, u2 = self.resolve_unit(from_unit), self.resolve_unit(to_unit)
        return self.category(u1) == self.category(u2) and self.category(u1) in ('volume','mass','count')

