class Ingredient:
    """
    Represents an ingredient entry: manages normalization, equality, and provides scaling.
    """
    def __init__(self, name, quantity, unit, normalizer=None):
        self.raw_name = name
        self.normalizer = normalizer
        self.name = normalizer.normalize_name(name) if normalizer else name.lower()
        self.quantity = float(quantity)
        self.unit = normalizer.normalize_unit(unit) if normalizer else unit.lower()
    def __repr__(self):
        return f"{self.quantity} {self.unit} {self.name}"
    def scale(self, factor):
        return Ingredient(self.raw_name, self.quantity * factor, self.unit, normalizer=self.normalizer)

class Recipe:
    """
    Holds a recipe's ingredients and serves, supports scaling and pretty printing.
    """
    def __init__(self, ingredients, servings, normalizer=None):
        self.ingredients = [Ingredient(ing.name, ing.quantity, ing.unit, normalizer) for ing in ingredients]
        self.servings = servings
        self.normalizer = normalizer
    def scale(self, new_servings):
        factor = float(new_servings) / self.servings
        scaled = [ing.scale(factor) for ing in self.ingredients]
        return Recipe(scaled, new_servings, normalizer=self.normalizer)
    def __repr__(self):
        return f"Recipe({self.servings} servings):\n" + '\n'.join([str(ing) for ing in self.ingredients])

class ShoppingList:
    """
    Aggregates, merges, converts, sorts and subtracts ingredients for shopping.
    """
    def __init__(self, normalizer=None):
        self.items = defaultdict(list)
        self.normalizer = normalizer
    def add_ingredient(self, ingredient):
        n = ingredient.name if not self.normalizer else self.normalizer.normalize_name(ingredient.name)
        u = ingredient.unit if not self.normalizer else self.normalizer.normalize_unit(ingredient.unit)
        self.items[n].append((ingredient.quantity, u))
    def merge(self, unit_converter, config=None):
        merged = {}
        for name, qlist in self.items.items():
            base_unit = None; base_total = 0
            pref_unit = config['unit_table'].get('preferred_units', {}).get(name)
            for qty, u in qlist:
                if pref_unit and unit_converter.can_convert(u, pref_unit):
                    bqty, bunit = unit_converter.to_base(qty, u)
                    base_qty2, _ = unit_converter.from_base(bqty, bunit, pref_unit)
                    base_total += base_qty2; base_unit = pref_unit
                else:
                    if not base_unit:
                        base_unit = u
                        base_total = qty
                    elif unit_converter.can_convert(u, base_unit):
                        bqty, bunit = unit_converter.to_base(qty, u)
                        bbqty, _ = unit_converter.from_base(bqty, bunit, base_unit)
                        base_total += bbqty
                    else:
                        # fallback add without conversion
                        base_total += qty
            merged[name] = {base_unit: round(base_total,2)}
        return merged
    def subtract_pantry(self, pantry):
        after = {}
        for name, units in self.items.items():
            if name in pantry:
                pantry_qty, pantry_unit = pantry[name]
                # only works if units match, else require conversion upstream
                total = sum(qty for qty, u in units if u == pantry_unit)
                after_qty = total - pantry_qty
                if after_qty > 0:
                    after[name] = {pantry_unit: round(after_qty,2)}
            else:
                # copy all
                after[name] = {u: round(q,2) for q, u in units}
        return after
